#!/bin/bash
# Submit every job of the sh/sr replicate experiment (generated by gen_scripts.py).
# Run download_models.sh first. Mind the 16-queued-jobs limit.
#   bash submit_all.sh                          # all seeds (42 123 456 789 2024)
#   SEED_LIST="42 123" bash submit_all.sh      # a subset
# The Slurm time limit is set from the number of seeds: estimated minutes per seed x
# seeds x 1.3, rounded up to whole hours. Re-submitting skips runs whose
# test_results.json already exists.
set -euo pipefail
HERE="/gpfs/home6/zzhang/em-emb/a-train-matcher/scripts/sh_sr_replicates"

read -r -a SEEDS <<< "${SEED_LIST:-42 123 456 789 2024}"
# "<script> <estimated minutes per seed>"
JOBS=(
    "job1_qwen3-8b-cross.sh 201"
    "job2_llama-3.1-8b-cross.sh 205"
    "job3_qwen3-8b-gen.sh 198"
    "job4_llama-3.1-8b-gen.sh 204"
    "job5_gemma-3-4b-cross.sh 192"
    "job6_qwen3-4b-cross.sh 206"
    "job7_gemma-3-4b-gen.sh 186"
    "job8_qwen3-4b-gen.sh 203"
)
for JOB in "${JOBS[@]}"; do
    read -r SCRIPT MIN_PER_SEED <<< "${JOB}"
    HOURS=$(( (MIN_PER_SEED * ${#SEEDS[@]} * 130 / 100 + 59) / 60 ))
    TIME=$(printf "%d-%02d:00:00" $((HOURS / 24)) $((HOURS % 24)))
    echo "${SCRIPT}: seeds ${SEEDS[*]}, time limit ${TIME}"
    SEED_LIST="${SEEDS[*]}" sbatch --export=ALL --time="${TIME}" "${HERE}/${SCRIPT}"
done
